  }
  return database;""","""    fillOpenJobs(database);
  }
  addRequestIds(database);
  return database;""")
s=s.replace("""export function openDatabase""","""// A wrench's request_id is the app's idempotency key: one key, one report, however often it is sent.
// Older spoke.db files get the column here; reports without a key (NULL) are never matched.
function addRequestIds(database: Database) {
  const columns = database.query("PRAGMA table_info(wrenches)").all() as { name: string }[];
  if (!columns.some((column) => column.name === "request_id")) {
    database.exec("ALTER TABLE wrenches ADD COLUMN request_id TEXT");
  }
  database.exec(
    "CREATE UNIQUE INDEX IF NOT EXISTS wrenches_request_id ON wrenches (request_id)",
  );
}

export function openDatabase""")
open(p,'w').write(s)

p='src/wrenches.ts'; s=open(p).read()
s=s.replace("type WrenchReport = { bike_id?: string; fault?: string };","type WrenchReport = { bike_id?: string; fault?: string; request_id?: string };")
s=s.replace("""  const fault = report.fault ?? "OTHER";
""","""  const fault = report.fault ?? "OTHER";
  const requestId = typeof report.request_id === "string" && report.request_id ? report.request_id : null;
""")
s=s.replace("""  const record = database.transaction(() => {
    const wrench = database
      .query("INSERT INTO wrenches (bike_id, station_id, fault, reported_at) VALUES (?, ?, ?, ?)")
      .run(bike_id, station_id, fault, reportedAt);""","""  const record = database.transaction(() => {
    // A retry carries the same request_id: it is the same report, so hand back its job and
    // write nothing. The first wrench's reported_at stays, as SLA-4's clock starts there.
    if (requestId) {
      const earlier = database
        .query("SELECT wrench_id FROM wrenches WHERE request_id = ?")
        .get(requestId) as { wrench_id: number } | null;
      if (earlier) return { jobId: `J-W-${earlier.wrench_id}`, isRepeat: true };
    }
    const wrench = database
      .query(
        "INSERT INTO wrenches (bike_id, station_id, fault, reported_at, request_id) VALUES (?, ?, ?, ?, ?)",
      )
      .run(bike_id, station_id, fault, reportedAt, requestId);""")
s=s.replace("""    return jobId;
  });
  const jobId = record();

  logEvent("wrench", { bike_id, station_id, fault, job_id: jobId });
  return { status: 201, body: { job_id: jobId, bike_id } };""","""    return { jobId, isRepeat: false };
  });
  const { jobId, isRepeat } = record();

  if (isRepeat) {
    logEvent("wrench_repeat", { bike_id, request_id: requestId, job_id: jobId });
    return { status: 200, body: { job_id: jobId, bike_id } };
  }
  logEvent("wrench", { bike_id, station_id, fault, job_id: jobId, request_id: requestId });
  return { status: 201, body: { job_id: jobId, bike_id } };""")
open(p,'w').write(s)
